export const W=900,H=1200;
/** Paper rhythm: lines every LINE px starting at RULE_START. Typed text uses the same LINE height, and its top
 * padding is chosen so each baseline sits just above a rule (rule = TEXT_TOP + (k+1)*LINE - 3). */
export const LINE=28,RULE_START=18,TEXT_SIZE=20,TEXT_TOP=77,TEXT_SIDE=78,TEXT_BASELINE=98;
export function stroke(ctx,s,from=0){const p=s.points;if(!p.length||from>=p.length)return;ctx.save();ctx.strokeStyle=s.color;ctx.fillStyle=s.color;ctx.globalAlpha=s.tool==='highlighter'?.3:1;ctx.lineCap='round';ctx.lineJoin='round';if(s.tool==='highlighter'){if(from>0){ctx.restore();return;}ctx.lineWidth=s.width*5;ctx.beginPath();ctx.moveTo(p[0][0],p[0][1]);for(const q of p.slice(1))ctx.lineTo(q[0],q[1]);if(p.length===1)ctx.lineTo(p[0][0]+.1,p[0][1]);ctx.stroke();}else{for(let i=from;i<p.length;i++){const a=p[Math.max(0,i-1)],b=p[i];ctx.lineWidth=s.width*(.35+.9*((a[2]+b[2])/2));ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.stroke();if(i===0){ctx.beginPath();ctx.arc(b[0],b[1],ctx.lineWidth/2,0,Math.PI*2);ctx.fill();}}}ctx.restore();}
export function renderInk(canvas,strokes){const c=canvas.getContext('2d');c.setTransform(1,0,0,1,0,0);c.clearRect(0,0,canvas.width,canvas.height);c.save();c.scale(canvas.width/W,canvas.height/H);for(const s of strokes)stroke(c,s);c.restore();}
export function paper(ctx,template){ctx.fillStyle='#101113';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#242527';ctx.fillStyle='#343435';ctx.lineWidth=.6;if(template==='dots'){for(let y=32;y<H;y+=28)for(let x=32;x<W;x+=28){ctx.beginPath();ctx.arc(x,y,.8,0,Math.PI*2);ctx.fill();}}else if(template==='grid'||template==='ruled'){for(let y=RULE_START;y<H;y+=LINE){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}if(template==='grid')for(let x=RULE_START;x<W;x+=LINE){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}}}
/** Decoded page photos, shared by thumbnails and exports. Returns the image once it can be drawn; until then onReady (if given) fires when it loads. */
const photoCache=new Map();
export function photoImage(src,onReady){let im=photoCache.get(src);if(!im){im=new Image();im.decoding='async';im.src=src;photoCache.set(src,im);if(photoCache.size>120)photoCache.delete(photoCache.keys().next().value);}if(im.complete&&im.naturalWidth)return im;if(onReady){im.addEventListener('load',onReady,{once:true});}return null;}
/** Resolves once every photo on these pages is decoded (or failed), so an export never misses one. */
export function photosReady(pages){return Promise.all(pages.flatMap(p=>(p.photos||[]).map(q=>new Promise(done=>{if(photoImage(q.src,done))return done();const im=photoCache.get(q.src);im.addEventListener('error',done,{once:true});if(im.complete)done();}))));}
export function pageImage(p,onPending){const c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d');paper(x,p.template);const drawPhotos=front=>{for(const q of p.photos||[]){if(!!q.front!==front)continue;const im=photoImage(q.src,onPending);if(im)x.drawImage(im,q.x,q.y,q.w,q.h);}};drawPhotos(false);x.fillStyle='#eee8db';x.font=`${TEXT_SIZE}px Georgia`;const wrap=W-2*TEXT_SIDE;let y=TEXT_BASELINE;for(const line of p.text.split('\n')){let current='';for(const word of line.split(' ')){if(x.measureText(current+word).width>wrap){x.fillText(current,TEXT_SIDE,y);y+=LINE;current='';}current+=word+' ';}x.fillText(current,TEXT_SIDE,y);y+=LINE;}for(const s of p.strokes)stroke(x,s);drawPhotos(true);return c;}
export function hitStroke(s,x,y,radius=16){return s.points.some((b,i)=>{const a=s.points[Math.max(0,i-1)],dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy||1)));return Math.hypot(x-a[0]-t*dx,y-a[1]-t*dy)<radius+(s.tool==='highlighter'?s.width*2.5:s.width);});}
